sealed class DecodeResult {
    
    data class Success(
        val v1: DecodedData) : DecodeResult() {
        companion object
    }
    
    object Buffering : DecodeResult()
    
    
    data class Unhandled(
        val `reason`: UnhandledReason, 
        val `frameData`: kotlin.ByteArray) : DecodeResult() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeDecodeResult : FfiConverterRustBuffer<DecodeResult>{
    override fun read(buf: ByteBuffer): DecodeResult {
        return when(buf.getInt()) {
            1 -> DecodeResult.Success(
                FfiConverterTypeDecodedData.read(buf),
                )
            2 -> DecodeResult.Buffering
            3 -> DecodeResult.Unhandled(
                FfiConverterTypeUnhandledReason.read(buf),
                FfiConverterByteArray.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: DecodeResult) = when(value) {
        is DecodeResult.Success -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeDecodedData.allocationSize(value.v1)
            )
        }
        is DecodeResult.Buffering -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is DecodeResult.Unhandled -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterTypeUnhandledReason.allocationSize(value.`reason`)
                + FfiConverterByteArray.allocationSize(value.`frameData`)
            )
        }
    }

    override fun write(value: DecodeResult, buf: ByteBuffer) {
        when(value) {
            is DecodeResult.Success -> {
                buf.putInt(1)
                FfiConverterTypeDecodedData.write(value.v1, buf)
                Unit
            }
            is DecodeResult.Buffering -> {
                buf.putInt(2)
                Unit
            }
            is DecodeResult.Unhandled -> {
                buf.putInt(3)
                FfiConverterTypeUnhandledReason.write(value.`reason`, buf)
                FfiConverterByteArray.write(value.`frameData`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}






