        companion object
    }
    
    data class Veteran(
        val v1: VeteranSettings) : WheelSettings() {
        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeWheelSettings : FfiConverterRustBuffer<WheelSettings>{
    override fun read(buf: ByteBuffer): WheelSettings {
        return when(buf.getInt()) {
            1 -> WheelSettings.None
            2 -> WheelSettings.Begode(
                FfiConverterTypeBegodeSettings.read(buf),
                )
            3 -> WheelSettings.Veteran(
                FfiConverterTypeVeteranSettings.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: WheelSettings) = when(value) {
        is WheelSettings.None -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
